package com.spinfit.bike.ui;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;
import com.spinfit.bike.app.*;import com.spinfit.bike.ble.*;import com.spinfit.bike.core.*;
public final class RideActivity extends Activity {
 private BikeSession s;private TextView clock,remaining,stage,power,cad,hr,speed,distance,calories,connection,target,actual,control,note,powerUnit,stageRemaining;
 private Button pause,auto,reconnect;private Visuals.Profile profile;private final Handler h=new Handler();private boolean visible,opening;private TextView minus,plus;
 private final Runnable refresh=new Runnable(){public void run(){if(!visible)return;render();h.postDelayed(this,500);}};
 @Override protected void onCreate(Bundle b){super.onCreate(b);s=BikeSession.get();s.init(this);if(s.engine()==null||s.program()==null){finish();return;}getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);TrainingProgram p=s.program();LinearLayout root=Ui.root(this);root.setPadding(Ui.dp(this,24),Ui.dp(this,8),Ui.dp(this,24),Ui.dp(this,24));
  root.addView(Ui.topBar(this,p.name,()->Ui.goTab(this,0)));LinearLayout times=Ui.row(this);LinearLayout left=Ui.col(this);left.addView(Ui.sub(this,"骑行时间"));clock=Ui.number(this,"00:00",34,Ui.TEXT);Ui.gap(this,left,5);left.addView(clock);Ui.weight(times,left);LinearLayout right=Ui.col(this);right.setGravity(Gravity.RIGHT);connection=Ui.pill(this,"等待连接",Ui.ACCENT);right.addView(connection);Ui.gap(this,right,8);remaining=Ui.sub(this,"");right.addView(remaining);times.addView(right);root.addView(times);Ui.gap(this,root,18);
  LinearLayout main=Ui.col(this);main.setGravity(Gravity.CENTER);powerUnit=Ui.tv(this,"实时功率 / W",12,Ui.DIM,true);main.addView(powerUnit);power=Ui.number(this,"—",86,Ui.ACCENT);main.addView(power);note=Ui.tv(this,"",12,Ui.DIM,false);note.setGravity(Gravity.CENTER);main.addView(note);reconnect=Ui.button(this,"重新连接当前单车",Ui.CARD2,Ui.TEXT);reconnect.setVisibility(View.GONE);reconnect.setOnClickListener(v->{if(s.reconnectCurrentBike())Toast.makeText(this,"正在重新连接原单车",Toast.LENGTH_SHORT).show();});main.addView(reconnect);root.addView(main);Ui.gap(this,root,22);
  LinearLayout data=Ui.card(this);data.setPadding(Ui.dp(this,16),Ui.dp(this,16),Ui.dp(this,16),Ui.dp(this,14));
  boolean largeText=getResources().getConfiguration().screenWidthDp<340||(getResources().getConfiguration().fontScale>1.35f&&getResources().getConfiguration().screenWidthDp<600);
  LinearLayout metrics=Ui.row(this);cad=bigMetric(metrics,"踏频 / rpm");hr=bigMetric(metrics,"心率 / bpm  ›");
  if(largeText){
   data.addView(metrics);dataDivider(data);LinearLayout second=Ui.row(this);speed=bigMetric(second,"速度 / km/h");distance=bigMetric(second,"单车里程 / km");data.addView(second);dataDivider(data);LinearLayout third=Ui.row(this);calories=bigMetric(third,"单车消耗 / kcal");data.addView(third);
  }else{
   speed=bigMetric(metrics,"速度 / km/h");data.addView(metrics);dataDivider(data);LinearLayout totals=Ui.row(this);distance=bigMetric(totals,"单车里程 / km");calories=bigMetric(totals,"单车消耗 / kcal");data.addView(totals);
  }
  android.view.View heartTile=(android.view.View)hr.getParent();Ui.touch(heartTile,Ui.CARD,14);heartTile.setContentDescription("连接或查看心率设备");heartTile.setOnClickListener(v->startActivity(new Intent(this,HeartRateActivity.class)));
  Ui.gap(this,data,12);heartSource=Ui.tv(this,"",11,Ui.DIM,false);heartSource.setGravity(Gravity.CENTER);data.addView(heartSource,new LinearLayout.LayoutParams(-1,-2));Ui.add(this,root,data,20);
  LinearLayout segment=Ui.card(this);segment.setPadding(Ui.dp(this,18),Ui.dp(this,16),Ui.dp(this,18),Ui.dp(this,16));LinearLayout title=Ui.row(this);stage=Ui.tv(this,"",17,Ui.TEXT,true);Ui.weight(title,stage);stageRemaining=Ui.tv(this,"",12,Ui.DIM,false);title.addView(stageRemaining);segment.addView(title);Ui.gap(this,segment,10);target=Ui.tv(this,"",12,Ui.DIM,false);segment.addView(target);Ui.gap(this,segment,14);profile=new Visuals.Profile(this,p);segment.addView(profile,new LinearLayout.LayoutParams(-1,Ui.dp(this,35)));Ui.add(this,root,segment,16);
  LinearLayout res=Ui.card(this);res.setPadding(Ui.dp(this,18),Ui.dp(this,16),Ui.dp(this,18),Ui.dp(this,16));LinearLayout heading=Ui.row(this);Ui.weight(heading,Ui.tv(this,"阻力控制",16,Ui.TEXT,true));auto=Ui.button(this,"自动",Ui.CARD2,Ui.ACCENT);auto.setTextSize(12);auto.setOnClickListener(v->{if(s.engine().isPaused())return;s.setAuto(!s.engine().isAutoResistance());render();});heading.addView(auto);res.addView(heading);Ui.gap(this,res,10);LinearLayout controls=Ui.row(this);minus=Ui.circleButton(this,"−",Ui.CARD2,Ui.TEXT);minus.setOnClickListener(v->adjust(-1));controls.addView(minus,new LinearLayout.LayoutParams(Ui.dp(this,56),Ui.dp(this,56)));LinearLayout center=Ui.col(this);center.setGravity(Gravity.CENTER);actual=Ui.number(this,"—",30,Ui.TEXT);center.addView(actual);control=Ui.tv(this,"",11,Ui.DIM,false);center.addView(control);Ui.weight(controls,center);plus=Ui.circleButton(this,"+",Ui.CARD2,Ui.TEXT);plus.setOnClickListener(v->adjust(1));controls.addView(plus,new LinearLayout.LayoutParams(Ui.dp(this,56),Ui.dp(this,56)));res.addView(controls);Ui.gap(this,res,12);TextView resNote=Ui.tv(this,"",12,Ui.DIM,false);resNote.setTag("resNote");res.addView(resNote);this.resNote=resNote;Ui.add(this,root,res,20);
  root.addView(Ui.sub(this,"设备未提供的字段显示 —。数据超过 4.5 秒未更新时暂停训练；恢复连接后点击继续。"));
  LinearLayout foot=Ui.row(this);foot.setPadding(Ui.dp(this,24),Ui.dp(this,12),Ui.dp(this,24),Ui.dp(this,12));foot.setBackgroundColor(Ui.BG);pause=Ui.primary(this,"暂停训练");pause.setOnClickListener(v->{if(s.engine().isPaused()){if(!s.resume())Ui.dialog(this,"等待单车数据","请确认单车电源与蓝牙连接，并踩动踏板。数据恢复后再点击继续。");}else s.pause();render();});Ui.weight(foot,pause);Button end=Ui.button(this,"结束",Ui.CARD2,Ui.TEXT);end.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("结束这次骑行？").setMessage("当前训练与有效数据将保存在本地记录中。").setNegativeButton("继续骑行",null).setPositiveButton("结束并保存",(d,w)->finishRide()).show());LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(Ui.dp(this,96),-2);ep.leftMargin=Ui.dp(this,12);foot.addView(end,ep);Ui.screen(this,root,foot);
 }
 private TextView resNote,heartSource;
 private void dataDivider(LinearLayout data){Ui.gap(this,data,16);data.addView(Ui.divider(this),new LinearLayout.LayoutParams(-1,Ui.dp(this,1)));Ui.gap(this,data,14);}
 private TextView bigMetric(LinearLayout parent,String name){LinearLayout c=Ui.col(this);c.setGravity(Gravity.CENTER);TextView v=Ui.number(this,"—",31,Ui.TEXT);v.setSingleLine(true);v.setHorizontallyScrolling(false);v.setAutoSizeTextTypeUniformWithConfiguration(18,31,1,android.util.TypedValue.COMPLEX_UNIT_SP);c.addView(v);Ui.gap(this,c,6);TextView label=Ui.tv(this,name,11,Ui.DIM,false);c.addView(label);Ui.weight(parent,c);return v;}
 private void adjust(int delta){s.adjustBy(delta);render();}
 private void render(){if(s.engine()==null)return;Metrics m=s.engine().snapshot();if(m.finished){showSaved();return;}BikeSource.Sample x=s.fresh()?s.lastSample():null;boolean paused=s.engine().isPaused();clock.setText(Ui.time(m.elapsedSec));remaining.setText(s.program().freeRide?"自由骑行 · 不限时":"剩余 "+Ui.time(m.remainingSec));connection.setText(!s.isConnected()?"连接已断开":s.isDemo()?"演示训练":s.fresh()?"单车已连接":"等待数据");connection.setTextColor(s.isDemo()||!s.fresh()?Ui.WARN:Ui.ACCENT);power.setText(x!=null&&x.powerValid?Ui.val(x.powerW,0):"—");cad.setText(x!=null&&x.cadenceValid?Ui.val(x.cadenceRpm,0):"—");int bpm=s.currentHeartRate();hr.setText(bpm>0?""+bpm:"—");hr.setTextColor(Ui.heartRateColor(bpm));heartSource.setText("心率来源："+s.heartSource()+" · 点心率可连接");speed.setText(x!=null&&x.speedValid?Ui.val(x.speedKph,1):"—");powerUnit.setText(s.isDemo()?"模拟功率 / W":"实时功率 / W");
  note.setText(!s.saveError().isEmpty()?s.saveError():paused?(s.dataPaused()?"数据中断，已自动暂停":"训练已暂停，准备好后继续"):s.isDemo()?(x!=null&&x.hrExternal?"演示单车 · 心率来自外部设备":"演示模式 · 所有数据均为模拟"):"保持顺畅踩踏，跟随自己的节奏");note.setTextColor(paused||s.isDemo()?Ui.WARN:Ui.DIM);reconnect.setVisibility(s.dataPaused()&&!s.isDemo()?View.VISIBLE:View.GONE);stage.setText(m.stageName);target.setText(s.program().freeRide?"自由调节阻力与踏频":"参考目标  "+Math.round(m.targetPowerW)+" W  ·  "+Math.round(m.targetCadence)+" rpm");profile.stage(m.stageIndex);int boundary=0;for(int i=0;i<=m.stageIndex&&i<s.program().segments.length;i++)boundary+=s.program().segments[i].durationSec;stageRemaining.setText(s.program().freeRide?"自主节奏":Ui.time(Math.max(0,boundary-m.elapsedSec)));int actualRes=x!=null&&x.resistanceValid?x.resistance:-1;actual.setText(actualRes>=0?""+actualRes:"—");int t=Math.round(m.targetResistance);control.setText(m.autoResistance?"单车实时阻力  /  课程目标 "+t:"单车实时阻力");auto.setText(m.autoResistance?"自动 · 已开":"手动 · 点击自动");auto.setTextColor(m.autoResistance?Ui.ACCENT:Ui.DIM);auto.setEnabled(!paused);plus.setEnabled(!paused);minus.setEnabled(!paused);plus.setAlpha(paused?.4f:1);minus.setAlpha(paused?.4f:1);
  BikeSource src=s.source();BikeSource.WriteResult w=s.lastWrite();boolean supported=src!=null&&src.supportsResistanceTarget();resNote.setText(!supported&&!s.isDemo()?"此单车未声明支持自动控阻，请手动旋转旋钮。":s.isDemo()?"演示阻力仅作用于模拟单车。":w!=null&&w.sent?(s.ble()!=null?s.ble().controlStatus():"目标已下发，实际档位以单车上报为准。"):w!=null?w.message:"连接后可调节阻力。");
  TelemetryStats stats=s.stats();distance.setText(stats!=null&&stats.distanceSeen?Ui.val(stats.distance,2):"—");calories.setText(stats!=null&&stats.caloriesSeen?Ui.val(stats.calories,0):"—");pause.setText(paused?"继续训练":"暂停训练");}
 private void finishRide(){s.finishWorkout();if(!s.saveError().isEmpty()){Ui.dialog(this,"未能保存",s.saveError());return;}showSaved();}
 private void showSaved(){if(opening)return;opening=true;SummaryActivity.open(this,s.recordId(),true);finish();}
 @Override protected void onResume(){super.onResume();visible=true;h.post(refresh);}
 @Override protected void onPause(){visible=false;h.removeCallbacks(refresh);super.onPause();}
 @Override public void onBackPressed(){Ui.goTab(this,0);}
 @Override protected void onDestroy(){h.removeCallbacksAndMessages(null);super.onDestroy();}
}
